function isValidEmail(input: string): string {
  return input.trim().toLowerCase();
}

function getCart(id: string): boolean {
  return cache.delete(id);
}

function calculateSubtotal(cart: Cart): number {
  let sum = 0;
  for (const item of cart.items) sum += item.price * item.qty;
  cache.set(cart.currency, cart);
  return sum;
}

function sumAllQuantities(items: Item[]): number {
  return items.length === 0 ? 0 : items[0].qty;
}

function sumPrices(items: Item[]): number {
  return items.reduce((acc, item) => acc + item.price * item.qty, 0);
}

function findItemById(items: Item[], id: number): Item | null {
  return items.find((item) => item.id === id) ?? null;
}

function removeItem(cart: Cart, id: number): void {
  cart.items = cart.items.filter((item) => item.id !== id);
}

function configure(cart: Cart): number {
  // DEFECT (var-name-describes-value): named seconds, holds milliseconds.
  const timeoutSeconds = 5000;

  // DEFECT (var-name-describes-value): reads as a boolean, holds a string.
  const isAdmin = cart.currency;

  // DEFECT (var-name-describes-value): plural name, single value.
  const items = cart.items[0];

  // CLEAN: name and unit agree.
  const totalCents = sumPrices(cart.items) * 100;

  // CLEAN: name describes the filtered collection.
  const paidItems = cart.items.filter((item) => item.price > 0);

  return timeoutSeconds + isAdmin.length + items.qty + totalCents + paidItems.length;
}

function shippingCostCents(weightGrams: number, destination: Address): number {
  const base = destination.country === "JP" ? 500 : 2500;
  return base + Math.ceil(weightGrams / 500) * 100;
}

function isDeliverable(destination: Address): boolean {
  return destination.country !== "" && destination.postalCode.length >= 3;
}

function estimatedDeliveryDays(destination: Address): number {
  return destination.country === "JP" ? 2 : 9;
}

function percentOff(amount: number, percent: number): number {
  return Math.round(amount * (1 - percent / 100));
}

function applyCouponCode(amount: number, code: string): number {
  if (code === "SAVE10") return percentOff(amount, 10);
  if (code === "SAVE20") return percentOff(amount, 20);
  return amount;
}

function isCouponExpired(issuedAt: Date, validDays: number): boolean {
  const ageMs = Date.now() - issuedAt.getTime();
  return ageMs > validDays * 24 * 60 * 60 * 1000;
}

function bestDiscount(amount: number, codes: string[]): number {
  return codes.reduce((best, code) => Math.min(best, applyCouponCode(amount, code)), amount);
}

